from torchvision import datasets, transformsfrom torch.utils.data import DataLoader#pip install gdowntransform = transforms.Compose([    transforms.Resize((64,64)),    transforms.ToTensor()])dataset = datasets.CelebA(    root="./data",    split="train",    download=True,    transform=transform)loader = DataLoader(    dataset,    batch_size=64,    shuffle=True)import torchimport torch.nn as nnclass Encoder(nn.Module):    def __init__(self, latent_dim):        super().__init__()        self.conv = nn.Sequential(            nn.Conv2d(                3,                32,                4,                2,                1            ),            nn.ReLU(),            nn.Conv2d(                32,                64,                4,                2,                1            ),            nn.ReLU(),            nn.Conv2d(                64,                128,                4,                2,                1            ),            nn.ReLU()        )        # 64x64 image becomes:        # 128 x 8 x 8        self.fc_mu = nn.Linear(            128*8*8,            latent_dim        )        self.fc_logvar = nn.Linear(            128*8*8,            latent_dim        )    def forward(self,x):        x=self.conv(x)        x=x.view(            x.size(0),            -1        )        mu=self.fc_mu(x)        logvar=self.fc_logvar(x)        return mu,logvar            class Decoder(nn.Module):    def __init__(self,latent_dim):        super().__init__()        self.fc = nn.Linear(            latent_dim,            128*8*8        )        self.deconv = nn.Sequential(            nn.ConvTranspose2d(                128,                64,                4,                2,                1            ),            nn.ReLU(),            nn.ConvTranspose2d(                64,                32,                4,                2,                1            ),            nn.ReLU(),            nn.ConvTranspose2d(                32,                3,                4,                2,                1            ),            nn.Sigmoid()        )    def forward(self,z):        x=self.fc(z)        x=x.view(            -1,            128,            8,            8        )        return self.deconv(x)                def reparameterize(mu, logvar):    std = torch.exp(        0.5 * logvar    )    eps = torch.randn_like(std)    z = mu + eps * std    return zclass VAE(nn.Module):    def __init__(self, latent_dim):        super().__init__()        self.encoder = Encoder(            latent_dim        )        self.decoder = Decoder(            latent_dim        )    def forward(self,x):        mu, logvar = self.encoder(x)        z = reparameterize(            mu,            logvar        )        reconstruction = self.decoder(z)        return reconstruction, mu, logvar        device = torch.device(    "cuda" if torch.cuda.is_available()    else "cpu")latent_dim = 128model = VAE(    latent_dim).to(device)print(device)def vae_loss(    reconstruction,    x,    mu,    logvar):    # reconstruction loss    recon_loss = nn.functional.binary_cross_entropy(        reconstruction,        x,        reduction="sum"    )    # KL divergence    kl_loss = -0.5 * torch.sum(        1         + logvar        - mu.pow(2)        - logvar.exp()    )    return recon_loss + kl_lossoptimizer = torch.optim.Adam(    model.parameters(),    lr=0.001)epochs = 20for epoch in range(epochs):    model.train()    total_loss = 0    for images, _ in loader:        images = images.to(device)        reconstruction, mu, logvar = model(            images        )        loss = vae_loss(            reconstruction,            images,            mu,            logvar        )        optimizer.zero_grad()        loss.backward()        optimizer.step()        total_loss += loss.item()    avg_loss = total_loss / len(loader)    print(        f"Epoch [{epoch+1}/{epochs}] Loss: {avg_loss:.2f}"    )        images,_ = next(iter(loader))image = images[0].unsqueeze(0)image = image.to(device)model.eval()with torch.no_grad():    reconstruction, mu, logvar = model(image)        original = image.cpu().squeeze()generated = reconstruction.cpu().squeeze()#visual original vs reconstruftuiredimport matplotlib.pyplot as pltplt.figure(figsize=(8,4))plt.subplot(1,2,1)plt.imshow(    original.permute(1,2,0))plt.title("Original")plt.axis("off")plt.subplot(1,2,2)plt.imshow(    generated.permute(1,2,0))plt.title("VAE Reconstruction")plt.axis("off")plt.show()#generate newz = torch.randn(    1,    latent_dim).to(device)model.eval()with torch.no_grad():    new_face = model.decoder(z)            new_face = new_face.cpu().squeeze()plt.imshow(    new_face.permute(1,2,0))plt.axis("off")plt.title("Generated Face")plt.show()torch.save(    model.state_dict(),    "celeba_vae.pth")model.load_state_dict(    torch.load("celeba_vae.pth"))